int hits = 0;
for (int i = 0; i < n_points; ++i) {
    double x = a + (b - a) * std::rand_r(&seed) / (static_cast<double>(RAND_MAX) + 1.0);
    double y = fmax * std::rand_r(&seed) / (static_cast<double>(RAND_MAX) + 1.0);
    if (y <= f(static_cast<double>(x))) {
        ++hits;
    }
}
return (static_cast<double>(hits) / n_points) * (b - a) * fmax;

